function each(text: string, re: RegExp, skip: Skip, fn: (m: RegExpExecArray) => void) {
  re.lastIndex = 0;
  let m: RegExpExecArray | null;
  while ((m = re.exec(text))) {
    if (skip(m.index)) continue;
    fn(m);
    if (!re.global) break;
  }
}

function wordOffsetInMatch(m: RegExpExecArray, word: string): { offset: number; length: number } {
  const idx = m[0].toLowerCase().lastIndexOf(word.toLowerCase());
  if (idx >= 0) return { offset: m.index + idx, length: word.length };
  return { offset: m.index, length: m[0].length };
}

export function checkContextSpelling(text: string, skip: Skip): Match[] {
  const matches: Match[] = [];
  const seen = new Set<string>();

  for (const rule of CONTEXT_RULES) {
    each(text, rule.word, skip, (m) => {
      const start = m.index;
      const end = start + m[0].length;
      const before = text.slice(Math.max(0, start - 80), start);
      const after = text.slice(end, end + 80);
      if (rule.before && !rule.before.test(before)) return;
      if (rule.after && !rule.after.test(after)) return;
      const key = `${rule.ruleId}:${start}`;
      if (seen.has(key)) return;
      seen.add(key);
      matches.push({
        offset: start,
        length: m[0].length,
        ruleId: rule.ruleId,
        category: "spelling",
        message: rule.message,
        explanation: rule.explanation,
        replacements: [rule.suggest],
      });
    });
  }

  for (const hint of PHRASE_HINTS) {
    each(text, hint.re, skip, (m) => {
      const wrong =
        hint.wrongWord ??
        (hint.re.source.includes("their") ? "their" : hint.re.source.includes("your") ? "your" : hint.re.source.includes("accept") ? "accept" : hint.re.source.includes("then") ? "then" : hint.re.source.includes("than") ? "than" : hint.re.source.includes("loose") ? "loose" : hint.re.source.includes("its") ? "its" : hint.re.source.includes("who's") ? "who's" : hint.re.source.includes("weather") ? "weather" : hint.re.source.includes("passed") ? "passed" : hint.re.source.includes("peak") ? "peak" : hint.re.source.includes("bare") ? "bare" : hint.re.source.includes("break") ? "break" : hint.re.source.includes("principle") ? "principle" : hint.re.source.includes("compliment") ? "compliment" : hint.re.source.includes("stationary") ? "stationary" : hint.re.source.includes("\\s+of") ? "of" : hint.re.source.includes("effect") ? "effect" : hint.re.source.includes("less") ? "less" : hint.re.source.includes("who\\b") ? "who" : hint.re.source.includes("advice") ? "advice" : hint.re.source.includes("breath") ? "breath" : hint.re.source.includes("desert") ? "desert" : hint.re.source.includes("peace") ? "peace" : hint.re.source.includes("quiet") ? "quiet" : hint.re.source.includes("sight") ? "sight" : hint.re.source.includes("cite") ? "cite" : hint.re.source.includes("roll") ? "roll" : hint.re.source.includes("hole") ? "hole" : hint.re.source.includes("moral") ? "moral" : hint.re.source.includes("capitol") ? "capitol" : hint.re.source.includes("illicit") ? "illicit" : hint.re.source.includes("eminent") ? "eminent" : hint.re.source.includes("illusion") ? "illusion" : hint.re.source.includes("aloud") ? "aloud" : hint.re.source.includes("personal") ? "personal" : hint.re.source.includes("precede") ? "precede" : hint.re.source.includes("lightening") ? "lightening" : hint.re.source.includes("everyday") ? "everyday" : hint.re.source.includes("every\\s+day") ? "every day" : "");
      const span = wrong ? wordOffsetInMatch(m, wrong) : { offset: m.index, length: m[0].length };
      const key = `${hint.ruleId}:${span.offset}`;
      if (seen.has(key)) return;
      seen.add(key);
      matches.push({
        offset: span.offset,
        length: span.length,
        ruleId: hint.ruleId,
        category: "spelling",
        message: hint.message,
        explanation: hint.explanation,
        replacements: [hint.suggest],
      });
    });
  }

  return matches;
}
